def pre(x):
    return And(x >= 0, x <= 9999)

def post(x, r):
    # Padded decimal digits of x, most significant first (4 positions).
    d = [x / 1000, (x / 100) % 10, (x / 10) % 10, x % 10]
    # Number of digits of x without leading zeros (x = 0 has one digit).
    n = If(x >= 1000, 4, If(x >= 100, 3, If(x >= 10, 2, 1)))
    # Padded 1-based position corresponding to the answer r.
    q = r + 4 - n

    def dv(idx):
        # Value of the digit at padded 1-based position idx (an expression in q).
        return If(idx == 1, d[0], If(idx == 2, d[1], If(idx == 3, d[2], d[3])))

    value_at_q = dv(q)

    conds = [And(r >= 1, r <= n)]
    # The digit at position r is a largest digit (leading zeros never exceed it).
    for j in range(1, 5):
        conds.append(value_at_q >= d[j - 1])
    # Every digit after position r is strictly smaller (last occurrence of the maximum).
    for j in range(1, 5):
        conds.append(Implies(q < j, d[j - 1] < value_at_q))
    return And(*conds)
